-- Airlinerra expansion Germany Batch 04, 2026-10-26, eight runway reviews.
-- Applied to private Supabase `airlinerra` research schema and audited PASS.
-- `CURRENT_AIRPORT_OPERATOR` evidence grade includes current operator technical
-- pages (EDMS,EDON,EDOV,EDQG,EDQM,EDRY) or operator and aviation-service-provider
-- joint corroboration (EDRZ); EDMO is an on-airport group, operator runway dimensions
-- not independently confirmed. Operator-specific airline permission is NOT verified.
-- Prerequisite: Batch01 creation of airlinerra.airport_expansion_independent_paved_runway_reviews.
-- Maintains original registry values and all founding 3140 gameplay entries.
DO $initial$ BEGIN
 IF (SELECT count(*) FROM airlinerra.airport_world_activation WHERE active AND world_number=1)<>3140
 OR EXISTS (SELECT 1 FROM airlinerra.airport_world_activation WHERE world_number<>1)
 THEN RAISE EXCEPTION 'World 1 scope not as authorized'; END IF;
END $initial$;

INSERT INTO airlinerra.airport_expansion_independent_paved_runway_reviews
(batch_key,airport_key,icao_code,research_status,source_authority_grade,paved_runway_pair,documented_physical_length_m,documented_width_m,normalized_surface,published_landing_direction_a_m,published_landing_direction_b_m,historic_registry_length_m,source_url,supporting_url,evidence_notes,next_review_action) VALUES
('EXPANSION_DE_PAVED_BATCH_04_2026_10_26','OURAIRPORTS:2252','EDMO','SECONDARY_RUNWAY_EVIDENCE_OFFICIAL_SOURCE_REQUIRED','SECONDARY_ONLY_CURRENT','04/22',2286,45,'ASPHALT',NULL,NULL,2286.0,'https://www.fsg-im-dlr.de/node/49','https://www.edmo-airport.de/flugbetrieb/','Resident on-airport DLR flying group states RW04/22 ASPHALT 2286x45m, qualifying physical length, and explicitly identifies EDMO as a Sonderflughafen with all traffic subject to airport-operator permission. Current TRIWO airport operator website confirms special purpose and PPR for business flights 2t-25t but does NOT publish same technical dimensions on inspected page. Do not misstate flying-club measurements as verified operator/aeronautical AIP; obtain current official source runway dimensions; retain HOLD_INDEPENDENT_VERIFICATION.','Require current original airport operator or effective German AIP source runway dimensions; special-airfield operator PPR is not itself runway evidence.'),
('EXPANSION_DE_PAVED_BATCH_04_2026_10_26','OURAIRPORTS:2253','EDMS','OPERATOR_RUNWAY_INDEPENDENTLY_CONFIRMED_RELEASE_HOLD','CURRENT_AIRPORT_OPERATOR','09/27',1350,30,'ASPHALT',1250,1350,1350.0,'https://www.airport-straubing.com/de/infos-fuer-piloten/airport-data/','https://www.airport-straubing.com/wp-content/uploads/2020/07/EDMS_Benutzungsordnung_20180601.pdf','Current airport operator runway 09/27 ASPHALT 1350x30m. RW09 TORA1350 (+60m additional paved strip by explicit permission) LDA1250m; RW27 TORA1250 (+40m additional strip) LDA1350m. An independent airfield directory lists 1470m but authoritative 2002 regulator notice establishes 1470m is protected runway strip (not asphalt runway). Do not use 1470m as landing pavement. PPR outside normal hours, specific commercial PPR conditions.','Confirm current German AIP runway-end landing/takeoff data, operator limitations and separately authorized later simulation airport expansion release; do not mark paid-airline rights verified.'),
('EXPANSION_DE_PAVED_BATCH_04_2026_10_26','OURAIRPORTS:2257','EDON','OPERATOR_RUNWAY_INDEPENDENTLY_CONFIRMED_RELEASE_HOLD','CURRENT_AIRPORT_OPERATOR','08/26',2400,50,'CONCRETE',NULL,NULL,2400.0,'https://www.airport-neuhardenberg.com/de/Service/Piloteninformationen/Piloteninformation.html','https://dulv.de/fmwebphp/Flugplatz/details.php?id=1022','Current airport operator identifies special-airfield EDON RW08/26 2400x50m concrete PCN53, 14.3m taxiway width, PPR outside operator discretion, fire Cat 3 (up to 6 PPR), and occasional on-runway events requiring preflight contact. No per-end declared LDA supplied; physical technical screen is not authorization for scheduled airline operation.','Confirm current German AIP runway-end landing/takeoff data, operator limitations and separately authorized later simulation airport expansion release; do not mark paid-airline rights verified.'),
('EXPANSION_DE_PAVED_BATCH_04_2026_10_26','OURAIRPORTS:2259','EDOV','OPERATOR_RUNWAY_INDEPENDENTLY_CONFIRMED_RELEASE_HOLD','CURRENT_AIRPORT_OPERATOR','08/26',1997,52,'CONCRETE',NULL,NULL,1997.0,'https://www.flugplatz-stendal.de/pilots/','https://www.flugplatz-stendal.de/geschichte-flugplatz-stendal-borstel/','Current airport-operator pilots page RW08/26 1997x52m concrete. Separate parallel 700x40m grass below 1200m. Older IVAO/DULV 1980m data conflicts with current operator 1997m; preserve 17m discrepancy and original registry. Aircraft <=5700kg normal, up to 14000kg PPR; outside hours 24-hour PPR, VFR only. Runway end LDA not established by source.','Confirm current German AIP runway-end landing/takeoff data, operator limitations and separately authorized later simulation airport expansion release; do not mark paid-airline rights verified.'),
('EXPANSION_DE_PAVED_BATCH_04_2026_10_26','OURAIRPORTS:43125','EDQG','OPERATOR_RUNWAY_INDEPENDENTLY_CONFIRMED_RELEASE_HOLD','CURRENT_AIRPORT_OPERATOR','08/26',1982,30,'CONCRETE',1847,1882,1981.8,'https://en.edqg.de/information-for-pilots/installations-for-vfr-und-ifr-flights','https://www.edqg.de/wp-content/uploads/2019/10/Benutzungsordn112019.pdf','Operator-hosted technical runway information RW08/26 concrete 1982x30m, displaced thresholds RW08 135m RW26 100m; runway08 LDA1847m TORA1882m; runway26 LDA1882m TORA1847m; PCN33, RFFS Category4 upgraded PPR. Commercial aircraft listed up to 14t, private to 25t, higher by explicit PPR. Operator source is long-lived and archived rules date 2019; effective 2026 German AIP confirmation outstanding before flight-specific use.','Confirm current German AIP runway-end landing/takeoff data, operator limitations and separately authorized later simulation airport expansion release; do not mark paid-airline rights verified.'),
('EXPANSION_DE_PAVED_BATCH_04_2026_10_26','OURAIRPORTS:2263','EDQM','OPERATOR_RUNWAY_INDEPENDENTLY_CONFIRMED_RELEASE_HOLD','CURRENT_AIRPORT_OPERATOR','08/26',1540,30,'ASPHALT',NULL,NULL,1480.1,'https://www.airport-hof.de/piloteninfo/flughafen-information','https://buchung.airport-hof.de/piloteninfo/','Current airport operator presents nonuniform runway END-SPECIFIC dimensions: length for 26 given 1540m with TORA1480m; length for 08 given 1240m with TORA1240m. Width 30m ASPH PCN30. Store 1540m as operator''s longest described physical figure for runway pair, but this DOES NOT assert RW08 has 1540m usable or published LDA; source effective AIP interpretation needed. Historical registry 1480m may reflect 26 takeoff length. Airport 14-20t PPR and rescue cat 6 PPR.','Confirm current German AIP runway-end landing/takeoff data, operator limitations and separately authorized later simulation airport expansion release; do not mark paid-airline rights verified.'),
('EXPANSION_DE_PAVED_BATCH_04_2026_10_26','OURAIRPORTS:2268','EDRY','OPERATOR_RUNWAY_INDEPENDENTLY_CONFIRMED_RELEASE_HOLD','CURRENT_AIRPORT_OPERATOR','16/34',1677,30,'ASPHALT',1400,1400,1676.7,'https://flugplatz-speyer.de/infos-entgelte/','https://de.ivao.aero/prozeduren/edgg/s/edry/','Current airport operator runway16/34 asphalt 1677x30m, TORA and published LDA 1400m in operator table, PCN40/F/C/X/T and grooved pavement. Separate 450m grass below requirement. MTOM normal <=10000kg, 20000kg PPR, >20t possibly PPR. Source currently notes PPR customs and night/weekend seasonal operating hours. Do not infer physical gross 1677m as available landing distance.','Confirm current German AIP runway-end landing/takeoff data, operator limitations and separately authorized later simulation airport expansion release; do not mark paid-airline rights verified.'),
('EXPANSION_DE_PAVED_BATCH_04_2026_10_26','OURAIRPORTS:2269','EDRZ','OPERATOR_RUNWAY_INDEPENDENTLY_CONFIRMED_RELEASE_HOLD','CURRENT_AIRPORT_OPERATOR','03/21',2675,45,'ASPHALT',NULL,NULL,2674.9,'https://www.essp-sas.eu/communication/news/essp-and-triwo-strengthen-ties-egnos-working-agreement-zweibrucken-airport/','https://www.edrz-airport.de/ueber-den-flugplatz/','2026 EGNOS service provider ESSP directly corroborates operator TRIWO and paved runway 03/21 length 2675m and current AFIS/PPR framework; official TRIWO airport operator lists roughly 2.7km runway and 24-hour PPR service. 45m width supported by independent IVAO Nov 2025 technical guide, not measured directly from operator site; current effective AIP width/landing distances still required. Restriction: 2018 downrated to Sonderlandeplatz, do not assume normal scheduled public-airline rights.','Confirm current German AIP runway-end landing/takeoff data, operator limitations and separately authorized later simulation airport expansion release; do not mark paid-airline rights verified.')
ON CONFLICT(batch_key,airport_key) DO NOTHING;

UPDATE airlinerra.airport_access_reviews a SET
 identity_status='VERIFIED',paved_runway_status='VERIFIED',
 review_status='INDEPENDENT_OPERATOR_PAVED_RUNWAY_VERIFIED_SIMULATION_RELEASE_PENDING',
 evidence_url=v.source_url,
 source_review_note='German expansion Batch 04 runway research only, operator/corroborating source: '||v.evidence_notes||' Next: '||v.next_review_action||' No game or commercial air carrier operating authority granted.',
 review_date='2026-10-26',last_updated=now()
FROM airlinerra.airport_expansion_independent_paved_runway_reviews v
JOIN airlinerra.airport_cohorts c ON c.airport_key=v.airport_key AND c.cohort='EXPANSION_3906'
WHERE a.airport_key=v.airport_key
AND v.batch_key='EXPANSION_DE_PAVED_BATCH_04_2026_10_26'
AND v.source_authority_grade='CURRENT_AIRPORT_OPERATOR'
AND a.review_status='HOLD_INDEPENDENT_VERIFICATION'
AND a.game_admission_status='NOT_APPROVED';

-- EDMO remains on source-verification hold due to only on-airport flying club
-- (not airport operator) providing detailed length/surface/width evidence.
-- Do NOT activate any expansion airport or update commercial approval.
SELECT icao_code,research_status,published_landing_direction_a_m,published_landing_direction_b_m
FROM airlinerra.airport_expansion_independent_paved_runway_reviews
WHERE batch_key='EXPANSION_DE_PAVED_BATCH_04_2026_10_26' ORDER BY icao_code;
